    $pawns[] = "myField-" . $i;
}
if(empty($pawns)) return;
$targetStr = implode("&", $pawns);
$chosen = await $player.MZChoose($targetStr);
if($chosen === "" || $chosen === "-" || $chosen === "PASS") return;
